using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;

    vector<vector<bool>> dp(n, vector<bool>(n, false));
    int best = 1;

    for (int i = 0; i < n; i++) dp[i][i] = true;

    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len <= n; i++) {
            int j = i + len - 1;
            if (s[i] == s[j] && (len == 2 || dp[i+1][j-1])) {
                dp[i][j] = true;
                best = len;
            }
        }
    }

    cout << best << endl;
    return 0;
